#include <vector>
#include <algorithm>

class Solution {
public:
    int longestArithmeticSubarray(std::vector<int>& nums) {
        int n = nums.size();
        if (n <= 2) return n;
        int ans = 2;
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < std::min(n, i + 3); ++j) {
                int step = (nums[j] - nums[i]) / (j - i);
                int modUsed = 0;
                int curLen = 0;
                for (int k = i; k < n; ++k) {
                    long long expected = (long long)nums[i] + (long long)(k - i) * step;
                    if (nums[k] == expected) {
                        curLen++;
                    } else {
                        if (modUsed == 0) {
                            modUsed = 1;
                            curLen++;
                        } else {
                            break;
                        }
                    }
                }
                ans = std::max(ans, curLen);
            }
        }
        return std::min(n, ans);
    }
};

